<!doctype html><html><head><meta charset="utf-8"><title>Questionnaire questions</title><style>body{font-family:Arial;background:#f4f6f8}main{max-width:1000px;margin:25px auto}.panel{background:#fff;padding:18px;margin:15px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}textarea,input{width:100%;box-sizing:border-box;padding:8px}</style></head><body><main><p><a href="<?= site_url('questionnaire/create') ?>">← Questionnaires</a></p><h1><?= esc($questionnaire['qn_title_eng']??$questionnaire['qn_title_th']??'Questionnaire') ?></h1><?php foreach($rows as $r): ?><div class="panel"><form method="post" action="<?= site_url('questionnaire/'.$questionnaire['qn_id'].'/questions/save') ?>"><?= csrf_field() ?><input type="hidden" name="qnde_id" value="<?= esc($r['qnde_id']) ?>"><div class="grid"><?php foreach(['qnde_heading_th','qnde_detail_th','qnde_heading_eng','qnde_detail_eng','qnde_heading_jp','qnde_detail_jp'] as $f): ?><label><?= esc($f) ?><textarea name="<?= esc($f) ?>"><?= esc($r[$f]) ?></textarea></label><?php endforeach ?></div><input name="qnde_status" value="<?= esc($r['qnde_status']) ?>"><button>Update</button></form></div><?php endforeach ?><div class="panel"><h2>Add question</h2><form method="post" action="<?= site_url('questionnaire/'.$questionnaire['qn_id'].'/questions/save') ?>"><?= csrf_field() ?><div class="grid"><?php foreach(['qnde_heading_th','qnde_detail_th','qnde_heading_eng','qnde_detail_eng','qnde_heading_jp','qnde_detail_jp'] as $f): ?><label><?= esc($f) ?><textarea name="<?= esc($f) ?>"></textarea></label><?php endforeach ?></div><input type="hidden" name="qnde_status" value="1"><button>Add</button></form></div></main></body></html>
